import os
import sys

print("CWD:", os.getcwd())
print("---- Files in workspace ----")
for root, dirs, files in os.walk("."):
    depth = root.count(os.sep)
    indent = "  " * depth
    print(f"{indent}{root}/")
    for f in sorted(files):
        fp = os.path.join(root, f)
        try:
            size = os.path.getsize(fp)
        except OSError as e:
            size = f"err:{e}"
        print(f"{indent}  {f} ({size} bytes)")

print("---- Python environment ----")
print(sys.version)
for mod in ["pypdf", "reportlab", "pdfplumber"]:
    try:
        m = __import__(mod)
        print(f"{mod}: OK version={getattr(m, '__version__', 'n/a')}")
    except Exception as e:
        print(f"{mod}: MISSING ({e})")

print("---- report.pdf probe (if present) ----")
target = "report.pdf"
if os.path.exists(target):
    try:
        from pypdf import PdfReader
        r = PdfReader(target)
        print("page_count:", len(r.pages))
        print("metadata:", r.metadata)
        try:
            t = r.pages[0].extract_text() or ""
            print("page1_text_start:", repr(t[:300]))
        except Exception as e:
            print("page1_text_extract_error:", e)
    except Exception as e:
        print("pypdf probe error:", e)
else:
    pdfs = [f for f in os.listdir(".") if f.lower().endswith(".pdf")]
    print("report.pdf NOT found. PDFs in cwd:", pdfs)
